  const questionIds = Array.isArray(record.question_ids) ? record.question_ids : null, responses = Array.isArray(record.responses) ? record.responses : null;
  const responseSemantics = detail.elements.find((element) => element.name === "responses");
  const conformance = profileConformance(value, profile), formal = state >= 2;
