    const exact = detail.elements.find((element) => element.name === name), inferred = exact ?? detail.elements.find((element) => element.values.some((candidate) => primitiveExecutionValues(fieldValue).some((primitive) => String(primitive) === String(candidate.value))));
    const valueMeanings = inferred?.values.filter((candidate) => primitiveExecutionValues(fieldValue).some((primitive) => String(primitive) === String(candidate.value))) ?? [];
    const definition = profile.properties[name];
