    const values = fixedValues ?? graph.statements
      .filter((statement) => predicates.includes(statement.predicate.value) && (statement.subject.id === primary?.id || predicates.includes(schema + "valueReference")))
      .map((statement) => describe(statement.object))
      .filter((value, index, all) => Boolean(value) && all.indexOf(value) === index);
