function FindabilityResultsDialog({ objectId, query, results, onClose }: { objectId: ObjectId; query: string; results: SearchResult[]; onClose: () => void }) {
  useEffect(() => { const close = (event: KeyboardEvent) => { if (event.key === "Escape") onClose(); }; document.addEventListener("keydown", close); return () => document.removeEventListener("keydown", close); }, [onClose]);
  const highlightedSnippet = (result: SearchResult) => {
    const text = result.snippet || "Empty matching line";
    if (!result.highlights.length) return text;
    const parts: ReactNode[] = [];
    let cursor = 0;
    result.highlights.forEach((range, index) => {
      if (range.start > cursor) parts.push(text.slice(cursor, range.start));
      parts.push(<mark className="searchMatchHighlight" key={`${range.start}-${range.end}-${index}`}>{text.slice(range.start, range.end)}</mark>);
      cursor = range.end;
    });
    if (cursor < text.length) parts.push(text.slice(cursor));
    return parts;
  };
  const groups = [
    { label: "EXACT MATCHES", results: results.filter((result) => result.kind.startsWith("Exact")) },
    { label: "CLOSE MATCHES", results: results.filter((result) => result.kind === "Close match") },
    { label: "PARTIAL MATCHES", results: results.filter((result) => result.kind === "Partial match") },
  ].filter((group) => group.results.length);
  return <div className="findabilityResultsBackdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section className="findabilityResultsDialog" role="dialog" aria-modal="true" aria-labelledby="findability-results-title"><header><div><span>Findability matches</span><h2 id="findability-results-title">{objectName(objectId)}</h2></div><div className="findabilityResultsQuery"><span>Searched for</span><q>{query}</q></div><strong>{results.length} {results.length === 1 ? "match" : "matches"}</strong><button type="button" onClick={onClose} aria-label="Close findability matches">×</button></header><div className="findabilityResultsBody">{groups.map((group) => <section className="searchResultGroup" aria-label={group.label.toLowerCase()} key={group.label}><div className="searchResultCategory">{group.label}</div>{group.results.map((result) => <article className="searchResult" key={`${result.objectId}/${result.file}/${result.line}`}><div className="resultMeta"><span>{result.file}</span><span>{`Line ${result.line}`}</span><em>{result.kind}</em></div><p>{highlightedSnippet(result)}</p></article>)}</section>)}</div></section></div>;
}

function FindabilityAuditDialog({ objectId, rows, onClose }: { objectId: ObjectId; rows: FindabilityAuditRow[]; onClose: () => void }) {
  const [auditPhase, setAuditPhase] = useState(0);
  useEffect(() => { const close = (event: KeyboardEvent) => { if (event.key === "Escape") onClose(); }; document.addEventListener("keydown", close); return () => document.removeEventListener("keydown", close); }, [onClose]);
  useEffect(() => {
    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const timings = reducedMotion ? [40, 80, 120] : [650, 1300, 2100];
    const timers = timings.map((delay, index) => window.setTimeout(() => setAuditPhase(index + 1), delay));
    return () => timers.forEach(window.clearTimeout);
  }, []);
  const expectedRows = rows.filter((row) => row.expected);
  const succeeded = expectedRows.filter((row) => row.results.length).length;
  const missed = expectedRows.length - succeeded;
  const unexpected = rows.filter((row) => row.status === "unexpected-found").length;
  const correctlyAbsent = rows.filter((row) => row.status === "correctly-absent").length;
  const statusLabel = (row: FindabilityAuditRow) => ({ "expected-found": "Found", "expected-missed": "Missed", "correctly-absent": "Not found", "unexpected-found": "Unexpected match" }[row.status]);
  const expectedFirst = rows.filter((row) => row.expected).sort((a, b) => a.term.localeCompare(b.term, undefined, { sensitivity: "base" }));
  const notExpected = rows.filter((row) => !row.expected).sort((a, b) => a.term.localeCompare(b.term, undefined, { sensitivity: "base" }));
  const renderAuditRow = (row: FindabilityAuditRow) => <tr className={row.status} key={row.term}><th scope="row">{row.term}</th><td>{row.expected ? "Yes" : "No"}</td><td><span className="auditStatus">{statusLabel(row)}</span></td><td>{evidence(row)}</td><td className="auditRationale"><span>{row.rationale}</span>{row.status === "unexpected-found" && <small>Unexpected match—the term appears in this KO’s findability metadata despite being outside its declared discovery focus.</small>}</td></tr>;
  const evidence = (row: FindabilityAuditRow) => {
    if (!row.results.length) return "—";
    const best = row.results.reduce((current, result) => result.rank < current.rank ? result : current);
    const kind = best.kind.startsWith("Exact") ? "Exact" : best.kind.replace(" match", "");
    return `${row.results.length} ${row.results.length === 1 ? "match" : "matches"} · ${kind}`;
  };
  const phaseText = ["Preparing 16 searches", "Searching findability metadata", "Comparing results with expectations"][Math.min(auditPhase, 2)];
  return <div className="findabilityAuditBackdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><section className="findabilityAuditDialog" role="dialog" aria-modal="true" aria-labelledby="findability-audit-title"><header><div><span>Findability search audit</span><h2 id="findability-audit-title">{objectName(objectId)}</h2></div><button type="button" onClick={onClose} aria-label="Close findability audit">×</button></header>{auditPhase < 3 ? <div className="findabilityAuditAcquisition" role="status" aria-live="polite"><span>Running Findability Audit</span><strong>{phaseText}</strong><i aria-hidden="true"><b /></i></div> : <div className="findabilityAuditBody auditResultsReveal"><section className="auditSummary" aria-label="Audit summary"><div><strong>{succeeded}<span> of {expectedRows.length}</span></strong><p>expected searches succeeded</p></div><dl><div><dt>Searches performed</dt><dd>{rows.length}</dd></div><div><dt>Expected searches missed</dt><dd>{missed}</dd></div><div><dt>Correctly absent</dt><dd>{correctlyAbsent}</dd></div><div><dt>Unexpected matches</dt><dd>{unexpected}</dd></div></dl></section><div className="auditTableWrap"><table className="findabilityAuditTable"><colgroup><col className="auditSearchColumn" /><col className="auditExpectedColumn" /><col className="auditResultColumn" /><col className="auditEvidenceColumn" /><col className="auditRationaleColumn" /></colgroup><thead><tr><th>Searched for</th><th>Expected</th><th>Audit result</th><th>Evidence</th><th>Why this result is expected</th></tr></thead><tbody>{expectedFirst.map(renderAuditRow)}<tr className="auditTableSectionGap" aria-hidden="true"><td colSpan={5} /></tr>{notExpected.map(renderAuditRow)}</tbody></table></div></div>}</section></div>;
}

