function RunnerOutputProjection({ model }: { model: any }) {
  return <div className="koRunnerResult" aria-live="polite">
    <div className={`koRunnerStatus ${model.status.tone}`}>{model.status.label}</div>
    <section className="koRunnerConclusion">
      <span>{model.conclusion.label}</span>
      <strong>{model.conclusion.value}</strong>
      {model.conclusion.detail && <p>{model.conclusion.detail}</p>}
    </section>
    {model.metrics?.length > 0 && <dl className="koRunnerMetrics">{model.metrics.map((item: any, index: number) => <div key={`${item.label}-${index}`}><dt>{item.label}</dt><dd>{item.value}</dd></div>)}</dl>}
    {model.sections?.map((section: any, sectionIndex: number) => section.rows?.length > 0 && <section className="koRunnerResultSection" key={`${section.title}-${sectionIndex}`}><h4>{section.title}</h4><dl>{section.rows.map((item: any, index: number) => <div key={`${item.label}-${index}`}><dt>{item.label}</dt><dd>{item.value}</dd></div>)}</dl></section>)}
    {model.notes?.length > 0 && <section className="koRunnerNotices"><h4>Supporting notes</h4><ul>{model.notes.map((note: string, index: number) => <li key={index}>{note}</li>)}</ul></section>}
    {model.warnings?.length > 0 && <section className="koRunnerNotices warning"><h4>Warnings</h4><ul>{model.warnings.map((warning: string, index: number) => <li key={index}>{warning}</li>)}</ul></section>}
    {model.errors?.length > 0 && <section className="koRunnerErrors" role="alert"><h4>Knowledge-object error</h4>{model.errors.map((error: any, index: number) => <article key={index}><strong>{error.code}</strong><p>{error.message}</p><small>{error.path === "Not supplied" ? "No field was identified." : `Field: ${error.path}`}</small></article>)}</section>}
  </div>;
}

type RunnerFailure = { kind: "initialization" | "execution" | "timeout" | "malformed-output"; title: string; summary: string; technical: string };

function runnerFailureInfo(error: unknown, phase: "initialization" | "execution"): RunnerFailure {
  const name = error instanceof Error ? error.name : "Error";
  const message = error instanceof Error ? error.message : "No technical reason was supplied.";
  if (name === "RunnerTimeoutError") return { kind: "timeout", title: "Execution timed out.", summary: "The operation did not finish within five seconds. Restore the Runner to try again.", technical: `${name}: ${message}` };
  if (name === "DataCloneError" || name === "RunnerMalformedOutputError") return { kind: "malformed-output", title: "Output unavailable.", summary: "The Runner returned a result that could not be represented safely as JSON.", technical: `${name}: ${message}` };
  if (phase === "initialization" || name === "RunnerInitializationError") return { kind: "initialization", title: "Runner unavailable.", summary: `The isolated Runner could not be prepared: ${message}`, technical: `${name}: ${message}` };
  return { kind: "execution", title: "Operation stopped.", summary: `The declared Runner operation did not complete: ${message}`, technical: `${name}: ${message}` };
}

function RunnerFailureView({ failure }: { failure: RunnerFailure }) {
  return <div className={`koRunnerFailure ${failure.kind}`} role="alert"><strong>{failure.title}</strong><p>{failure.summary}</p><details><summary>Technical details</summary><code>{failure.technical}</code></details></div>;
}

function RunnerLookupInput({ field, value, onChange }: { field: any; value: string | number; onChange: (value: string) => void }) {
  const options = Array.isArray(field.options) ? field.options : [];
  const selected = options.find((option: any) => option.value === value);
  const [text, setText] = useState(selected?.label ?? "");
  const listId = `runner-${field.key}-options`;
  useEffect(() => { setText(selected?.label ?? ""); }, [selected?.label]);
  const accept = (candidate: string) => {
    setText(candidate);
    const option = options.find((item: any) => item.label === candidate);
    if (option) onChange(option.value);
  };
  return <span className="koRunnerLookup">
    <input type="search" list={listId} value={text} placeholder="Search by facility, location, or E-ID" autoComplete="off" aria-label={`Search ${field.label}`} aria-describedby={`${listId}-help`} onChange={(event) => accept(event.target.value)} onBlur={() => setText(selected?.label ?? "")} />
    <small id={`${listId}-help`}>{options.length ? `${options.length} selectable facilities` : "Facility roster unavailable"}</small>
    <datalist id={listId}>{options.map((option: any) => <option key={option.value} value={option.label} />)}</datalist>
  </span>;
}

function KnowledgeObjectRunnerView({ objectId, bundleSource, knowledgeObjectId, onClose }: { objectId: ObjectId; bundleSource: string; knowledgeObjectId: string; onClose: () => void }) {
  const inputConfig = useMemo(() => runnerInputConfig(knowledgeObjectId, (file: string) => canonicalSeedValue(objectId, file)), [knowledgeObjectId, objectId]);
  const openingFormState = useMemo<Record<string, string | number>>(() => inputConfig ? runnerExampleState(inputConfig) : {}, [inputConfig]);
  const [formState, setFormState] = useState<Record<string, string | number>>(() => ({ ...openingFormState }));
  const [hostState, setHostState] = useState<"preparing" | "ready" | "running" | "error" | "timeout">("preparing");
  const [sandboxGeneration, setSandboxGeneration] = useState(0);
  const [runnerOutput, setRunnerOutput] = useState<unknown>(null);
  const [runnerHasResult, setRunnerHasResult] = useState(false);
  const [runnerFailure, setRunnerFailure] = useState<RunnerFailure | null>(null);
  const sandboxRef = useRef<ReturnType<typeof createDisposableRunnerSandbox> | null>(null);
  useEffect(() => {
    const close = (event: KeyboardEvent) => { if (event.key === "Escape") onClose(); };
    document.addEventListener("keydown", close);
    return () => document.removeEventListener("keydown", close);
  }, [onClose]);
  useEffect(() => {
    let sandbox: ReturnType<typeof createDisposableRunnerSandbox>;
    try { sandbox = createDisposableRunnerSandbox({ bundleSource }); }
    catch (error) { setHostState("error"); setRunnerFailure(runnerFailureInfo(error, "initialization")); return; }
    sandboxRef.current = sandbox;
    let current = true;
    sandbox.ready.then(() => { if (current) setHostState("ready"); }).catch((error) => { sandbox.dispose(); if (current) { setHostState("error"); setRunnerFailure(runnerFailureInfo(error, "initialization")); } });
    return () => { current = false; sandbox.dispose(); sandboxRef.current = null; };
  }, [bundleSource, sandboxGeneration]);
  const executeRunner = async (input: unknown) => {
    if (hostState !== "ready" || !sandboxRef.current) return;
    setHostState("running");
    setRunnerFailure(null);
    try {
      const result = await sandboxRef.current.run(input);
      let exactJson: string | undefined;
      try { exactJson = JSON.stringify(result, null, 2); }
      catch (error) { const malformed = new Error(error instanceof Error ? error.message : "The returned value is not valid JSON."); malformed.name = "RunnerMalformedOutputError"; throw malformed; }
      if (typeof exactJson !== "string") { const malformed = new Error("The returned value is not valid JSON."); malformed.name = "RunnerMalformedOutputError"; throw malformed; }
      setRunnerOutput(result);
      setRunnerHasResult(true);
      setHostState("ready");
    } catch (error) {
      const timedOut = error instanceof Error && error.name === "RunnerTimeoutError";
      setHostState(timedOut ? "timeout" : "error");
      setRunnerFailure(runnerFailureInfo(error, "execution"));
    }
  };
  const restoreRunner = () => {
    sandboxRef.current?.reset();
    setRunnerOutput(null);
    setRunnerHasResult(false);
    setRunnerFailure(null);
    setHostState("preparing");
    setFormState({ ...openingFormState });
    setSandboxGeneration((value) => value + 1);
  };
  const inputAvailable = Boolean(inputConfig);
  const runnerInput: unknown = inputConfig ? createRunnerInput(inputConfig, formState) : null;
  const outputProjection = runnerHasResult ? projectRunnerOutput(inputConfig, runnerOutput) : null;
  const formMatchesOpeningState = JSON.stringify(formState) === JSON.stringify(openingFormState);
  const canRestore = !formMatchesOpeningState || runnerHasResult || Boolean(runnerFailure);
  const updateField = (key: string, value: string | number) => setFormState((current) => ({ ...current, [key]: value }));
  return <div className="koRunnerBackdrop" role="presentation">
    <section className="koRunnerDialog" role="dialog" aria-modal="true" aria-labelledby="ko-runner-view-title">
      <header><div><span>Browser Runner</span><h2 id="ko-runner-view-title">Run · {objectName(objectId)}</h2>{inputConfig?.operationScope && <p className="koRunnerScope">{inputConfig.operationScope}</p>}</div><button type="button" onClick={onClose} aria-label="Close Runner">×</button></header>
      <div className="koRunnerBody">
        <section className="koRunnerPane koRunnerInput" aria-labelledby="ko-runner-input-title">
          <header><div><span>Input</span><h3 id="ko-runner-input-title">{inputConfig?.title ?? "Operation input"}</h3></div><div className="koRunnerControls"><button className="koRunnerRestore" type="button" onClick={restoreRunner} disabled={!canRestore || hostState === "preparing" || hostState === "running"}>Restore</button><button className="koRunnerRun" type="button" onClick={() => executeRunner(runnerInput)} disabled={!inputAvailable || hostState !== "ready"}>Run</button></div></header>
          {inputConfig ? <div className="koRunnerForm" aria-busy={hostState === "preparing" || hostState === "running"}><p className="koRunnerHostStatus" aria-live="polite">{hostState === "preparing" ? "Preparing isolated Runner…" : hostState === "running" ? "Running…" : hostState === "timeout" ? "Execution timed out. Restore to try again." : hostState === "error" ? runnerFailure?.title ?? "Runner unavailable." : formMatchesOpeningState ? `${inputConfig.exampleName} loaded.` : "Input edited."}</p>{inputConfig.fields.map((field: any) => <label className={`koRunnerField ${field.type}`} key={field.key}><span>{field.label}</span>{field.type === "segmented" ? <span className="koRunnerSegments" role="group" aria-label={field.label}>{field.options.map((option: any) => <button type="button" key={option.value} className={String(formState[field.key]) === option.value ? "active" : ""} aria-pressed={String(formState[field.key]) === option.value} onClick={() => updateField(field.key, option.value)}>{option.label}</button>)}</span> : field.type === "number" ? <span className="koRunnerQuantity"><input type="number" value={formState[field.key]} min={field.min} step={field.step} onChange={(event) => updateField(field.key, event.target.value)} />{field.unit && <small>{field.unit}</small>}</span> : field.type === "lookup" ? <RunnerLookupInput field={field} value={formState[field.key]} onChange={(value) => updateField(field.key, value)} /> : <select value={formState[field.key]} onChange={(event) => updateField(field.key, event.target.value)}>{field.options.map((option: any) => <option key={option.value} value={option.value}>{option.label}</option>)}</select>}</label>)}<details className="koRunnerRequestSource"><summary>Generated request</summary><pre><code>{JSON.stringify(runnerInput, null, 2)}</code></pre></details></div> : <div className="koRunnerEmpty" role="alert"><strong>Input configuration unavailable.</strong><p>This Runner cannot be used until a human-readable input configuration is supplied.</p></div>}
        </section>
        <section className="koRunnerPane koRunnerOutput" aria-labelledby="ko-runner-output-title">
          <header><div><span>Output</span><h3 id="ko-runner-output-title">Operation result</h3></div></header>
          {runnerFailure ? <RunnerFailureView failure={runnerFailure} /> : runnerHasResult ? <RunnerOutputProjection model={outputProjection} /> : <div className="koRunnerEmpty"><strong>No result yet.</strong><p>Run the knowledge object to inspect its output.</p></div>}
        </section>
      </div>
    </section>
  </div>;
}

function graphicAbstractFile(files: FileName[]) {
  return files.find((file) => /^graphic\.abstract\.webp$/i.test(file))
    ?? files.find((file) => /^graphic\.abstract\.png$/i.test(file));
}

function graphicLogicFile(files: FileName[]) {
  return files.find((file) => /^graphic\.logic\.webp$/i.test(file));
}

function graphicAbstractMimeType(file: FileName) {
  return /\.webp$/i.test(file) ? "image/webp" : "image/png";
}

const PURPOSE_NOT_DECLARED = "Purpose not declared in findability metadata.";

function knowledgeObjectPurpose(objectId: ObjectId, drafts: Drafts) {
  const source = workingFileValue(objectId, "findability.metadata.txt", drafts);
  const graph = buildCanonicalRdfGraph(source);
  const primary = graph.statements.find((statement) => statement.subject.termType !== "BlankNode")?.subject;
  const predicates = ["https://schema.org/abstract", "https://schema.org/description"];
  for (const predicate of predicates) {
    const value = graph.statements.find((statement) => statement.subject.id === primary?.id && statement.predicate.value === predicate)?.object.value.trim();
    if (value) return value;
  }
  return PURPOSE_NOT_DECLARED;
}

function knowledgeObjectByteSize(objectId: ObjectId) {
  const encoder = new TextEncoder();
  return filesForObject(objectId).reduce((total, file) => {
    const key = draftKey(objectId, file);
    const binary = objectBinaryOverrides[key];
    if (binary !== undefined) {
      const padding = binary.match(/=*$/)?.[0].length ?? 0;
      return total + Math.max(0, Math.floor(binary.length * 3 / 4) - padding);
    }
    return total + encoder.encode(objectFileOverrides[key] ?? "").byteLength;
  }, 0);
}

function formatKnowledgeObjectSize(bytes: number) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(bytes < 10 * 1024 ? 1 : 0)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function knowledgeElementCount(objectId: ObjectId, drafts: Drafts) {
  try {
    const metadata = JSON.parse(workingFileValue(objectId, "metadata.json", drafts));
    const elements = metadata["koio:hasKnowledge"] ?? metadata.hasKnowledge;
    if (Array.isArray(elements)) return String(elements.length);
    if (elements && typeof elements === "object") return "1";
    return "Metadata issue";
  } catch {
    return "Metadata issue";
  }
}

function knowledgeImplementationFiles(objectId: ObjectId, drafts: Drafts) {
  const available = filesForObject(objectId);
  const declared = new Set<FileName>();
  try {
    const metadata = JSON.parse(workingFileValue(objectId, "metadata.json", drafts));
    const elements = metadata["koio:hasKnowledge"] ?? metadata.hasKnowledge;
    const list = Array.isArray(elements) ? elements : elements && typeof elements === "object" ? [elements] : [];
    list.forEach((element: any) => {
      const implementations = Array.isArray(element?.implementedBy) ? element.implementedBy : element?.implementedBy ? [element.implementedBy] : [];
      implementations.forEach((implementation: any) => {
        const path = String(implementation?.["@id"] ?? implementation ?? "").replace(/^\.\//, "");
        const match = available.find((file) => file === path || file === `implementation/${path}`);
        if (match) declared.add(match);
      });
    });
  } catch { /* Invalid metadata declares no implementation files. */ }
  return declared;
}

function knowledgeObjectMethod(objectId: ObjectId, drafts: Drafts) {
  const graph = buildCanonicalRdfGraph(workingFileValue(objectId, "findability.metadata.txt", drafts));
  const name = graph.statements.find((statement) => statement.predicate.value === "https://schema.org/name" && statement.object.value.trim().toLowerCase() === "computational method");
  if (!name) return "Not declared";
  return graph.statements.find((statement) => statement.subject.id === name.subject.id && statement.predicate.value === "https://schema.org/value")?.object.value.trim() || "Not declared";
}

